import { prepareDocuments } from './lib/document-input.js'
import { requiredShipmentFields, shipmentSchema, type Shipment } from './lib/shipment.js'

type Stage = 'Uploading' | 'Reading documents' | 'Extracting shipment data' | 'Validating extracted data' | 'Ready for review' | 'Failed'

type State = {
  stage: Stage
  files: File[]
  shipment: Shipment | null
  error: string | null
}

const field = <T>(value: T | null, confidence = value === null ? 0 : 1) => ({ value, confidence })

function emptyShipment(): Shipment {
  return shipmentSchema.parse({
    importer: { name: field(null), address: field(null), taxId: field(null) },
    consignee: { name: field(null), address: field(null) },
    seller: { name: field(null), address: field(null) },
    invoice: { number: field(null), date: field(null), currency: field(null), incoterm: field(null) },
    transport: { processingPort: field(null), entryPort: field(null), loadingPort: field(null), dischargePort: field(null), vessel: field(null), voyage: field(null), billOfLading: field(null), arrivalDate: field(null), containers: [] },
    entry: { type: field(null), bondType: field(null), date: field(null) },
    totals: { packages: field(null), grossWeight: field(null), freight: field(null), insurance: field(null), assists: field(null) },
    lines: [{ description: field(null), countryOfOrigin: field(null), htsCode: field(null), quantity: field(null), unit: field(null), value: field(null) }],
    conflicts: [],
  })
}

const state: State = { stage: 'Uploading', files: [], shipment: null, error: null }
const stages: Stage[] = ['Uploading', 'Reading documents', 'Extracting shipment data', 'Validating extracted data', 'Ready for review']
const apiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? (location.hostname === 'localhost' ? 'http://localhost:8787' : '')

function escapeHtml(value: unknown): string {
  return String(value ?? '').replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[character]!)
}

function getValue(shipment: Shipment, path: string): unknown {
  return path.split('.').reduce<unknown>((value, key) => (value as Record<string, unknown>)?.[key], shipment)
}

function setValue(shipment: Shipment, path: string, value: string): void {
  const keys = path.split('.')
  const target = keys.slice(0, -1).reduce<Record<string, unknown>>((current, key) => current[key] as Record<string, unknown>, shipment as unknown as Record<string, unknown>)
  const fieldValue = target[keys.at(-1)!] as { value: string | number | null }
  fieldValue.value = value || null
  fieldValue.confidence = 1
}

function missingFields(shipment: Shipment): string[] {
  return requiredShipmentFields.filter((path) => {
    const value = getValue(shipment, path) as { value?: unknown } | undefined
    return value?.value == null || value.value === ''
  })
}

function input(path: string, label: string): string {
  const extracted = getValue(state.shipment!, path) as { value: unknown; confidence: number }
  const status = extracted.value == null ? 'missing' : extracted.confidence < 0.75 ? 'low-confidence' : ''
  return `<label class="field ${status}"><span>${label}</span><input data-field="${path}" value="${escapeHtml(extracted.value)}" /><small>${extracted.value == null ? 'Missing' : `${Math.round(extracted.confidence * 100)}% confidence`}</small></label>`
}

function reviewMarkup(shipment: Shipment): string {
  const missing = missingFields(shipment)
  const conflicts = shipment.conflicts.map((conflict) => `<li><strong>${escapeHtml(conflict.field)}</strong>: ${escapeHtml(conflict.values.join(' / '))}</li>`).join('')
  const line = shipment.lines[0]

  return `
    <section class="review" aria-labelledby="review-heading">
      <div class="section-heading"><div><p class="eyebrow">Review</p><h2 id="review-heading">Confirm shipment data</h2></div><button type="button" id="reset-review" class="secondary">Reset</button></div>
      ${missing.length ? `<aside class="notice warning"><strong>Missing required fields</strong><ul>${missing.map((path) => `<li>${escapeHtml(path)}</li>`).join('')}</ul></aside>` : '<aside class="notice success">Required review fields are complete.</aside>'}
      ${conflicts ? `<aside class="notice warning"><strong>Conflicts</strong><ul>${conflicts}</ul></aside>` : ''}
      <div class="form-grid">
        <fieldset><legend>Parties</legend>${input('importer.name', 'Importer name')}${input('importer.taxId', 'Importer tax ID')}${input('consignee.name', 'Ultimate consignee')}${input('seller.name', 'Seller')}</fieldset>
        <fieldset><legend>Invoice</legend>${input('invoice.number', 'Invoice number')}${input('invoice.date', 'Invoice date')}${input('invoice.currency', 'Currency')}${input('invoice.incoterm', 'Incoterm')}</fieldset>
        <fieldset><legend>Transport</legend>${input('transport.processingPort', 'Processing port')}${input('transport.entryPort', 'Entry port')}${input('transport.billOfLading', 'Bill of lading')}${input('transport.arrivalDate', 'Arrival date')}</fieldset>
        <fieldset><legend>Entry</legend>${input('entry.type', 'Entry type')}${input('entry.bondType', 'Bond type')}${input('entry.date', 'Entry date')}</fieldset>
      </div>
      <fieldset><legend>First invoice line</legend><div class="form-grid lines">${input('lines.0.description', 'Description')}${input('lines.0.countryOfOrigin', 'Country of origin')}${input('lines.0.htsCode', 'HTS code')}${input('lines.0.quantity', 'Quantity')}${input('lines.0.unit', 'Unit')}${input('lines.0.value', 'Value')}</div></fieldset>
      <button type="button" id="generate-xml" disabled title="XML generation is implemented in the next step.">Generate NetCHB XML</button>
    </section>`
}

function render(): void {
  const currentStage = stages.indexOf(state.stage)
  document.querySelector<HTMLDivElement>('#app')!.innerHTML = `
    <main>
      <header><p class="eyebrow">NetCHB entry preparation</p><h1>Shipment to reviewed entry data</h1><p class="lede">Upload shipping documents, review extracted facts, then generate validated XML.</p></header>
      <ol class="stages">${stages.map((stage, index) => `<li class="${index < currentStage ? 'complete' : index === currentStage ? 'active' : ''}">${escapeHtml(stage)}</li>`).join('')}</ol>
      ${state.error ? `<aside class="notice error" role="alert">${escapeHtml(state.error)}</aside>` : ''}
      <section class="upload" aria-labelledby="upload-heading">
        <h2 id="upload-heading">Shipment documents</h2>
        <p>PDF, PNG, JPEG, WebP, text, and CSV files are supported. Scanned PDF pages are rendered for AI extraction.</p>
        <label class="drop-zone" for="documents"><span>Select files</span><input id="documents" type="file" multiple accept="application/pdf,image/jpeg,image/png,image/webp,text/plain,text/csv,.csv" /></label>
        ${state.files.length ? `<ul class="files">${state.files.map((file) => `<li>${escapeHtml(file.name)} <span>${Math.ceil(file.size / 1024)} KB</span></li>`).join('')}</ul>` : ''}
        <button type="button" id="extract" ${state.files.length ? '' : 'disabled'}>Extract shipment data</button>
      </section>
      ${state.shipment ? reviewMarkup(state.shipment) : ''}
    </main>`

  document.querySelector<HTMLInputElement>('#documents')?.addEventListener('change', (event) => {
    state.files = Array.from((event.target as HTMLInputElement).files ?? [])
    state.error = null
    state.stage = 'Uploading'
    render()
  })
  document.querySelector<HTMLButtonElement>('#extract')?.addEventListener('click', extract)
  document.querySelector<HTMLButtonElement>('#reset-review')?.addEventListener('click', () => { state.shipment = emptyShipment(); render() })
  document.querySelectorAll<HTMLInputElement>('[data-field]').forEach((element) => element.addEventListener('input', () => {
    if (!state.shipment) return
    setValue(state.shipment, element.dataset.field!, element.value)
    render()
  }))
}

async function extract(): Promise<void> {
  try {
    state.error = null
    state.stage = 'Reading documents'
    render()
    const payload = await prepareDocuments(state.files)
    state.stage = 'Extracting shipment data'
    render()
    const response = await fetch(`${apiBaseUrl}/api/extract`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) })
    const result = await response.json() as { shipment?: Shipment; error?: string }
    if (!response.ok || !result.shipment) throw new Error(result.error ?? 'Shipment extraction failed.')
    state.stage = 'Validating extracted data'
    state.shipment = shipmentSchema.parse(result.shipment)
    state.stage = 'Ready for review'
  } catch (error) {
    state.stage = 'Failed'
    state.error = error instanceof Error ? error.message : 'Shipment extraction failed.'
  }
  render()
}

render()
"
